namespace GoddessTempleDiscovery.Rules.Content;

public static partial class Catalog
{
    private static readonly string[] PrologueParagraphs =
    {
        // Title
        "Before the first spade",

        // Sheet 18 Part A, entry A0 (Loftus, 1849 and 1853); Open Question 10
        "In 1849 William Loftus, a member of the Turco-Persian Boundary Commission, visited the ruins of Uruk. In 1853 he came back and stayed for three months. He took finds to the British Museum, most of them from the late Seleucid and Parthian ages, and he met very old buildings near the ziggurat of Holy Inanna. One wall of colored clay cones that he uncovered is still called the Loftus Façade.",

        // Sheet 18 Part A, entry A0 (Koldewey and Sachau 1898, Andrae 1902, why so late)
        "Robert Koldewey and Eduard Sachau made a short visit in 1898, and Walter Andrae came in 1902. Their visits showed the great scientific promise of the ruins. But Uruk was hard to reach. Only the al-Hindiya Dam near Hilla and the coming of the automobile made the south easier to travel.",

        // Sheet 18 Part A, entry A0 (Eduard Meyer's demand)
        "The historian Eduard Meyer hoped for finds from the very earliest times, and he pushed for a dig. Even before the work began, the leaders of the German Oriental Society (Deutsche Orient-Gesellschaft) told the excavators to look into the city's oldest layers.",

        // Sheet 18 Part A, entry A0 (the Ottoman permit) and entry A1
        "The permit came from the Ottoman Empire in Constantinople. The German Consulate sent it on through the German Oriental Society, and its envelope still survives. Julius Jordan and the architect Conrad Preusser began work on 13 November 1912. Foremen and workers from Babylon and Hilla ran the camp and hired bedouin of the Tobe and Istshey tribes.",

        // Sheet 18 Part A, entry A1 (the four tasks of 1912/13)
        "The first season had four tasks. Make the first accurate map of the city. Dig into the Resh Sanctuary, a huge late temple that looters had been robbing. Take a first look at the high mound of Holy Inanna's ziggurat. And dig a little in the west, where looters' pits showed the palace of King Sin-kashid. The large-scale work in Her precinct, Eanna, would have to wait until 1928.",
    };

    private static readonly string[] EpilogueParagraphs =
    {
        // Title
        "After 1939",

        // Sheet 18 Part A, entry A14 (1939 to 1953/54, Frankfort, Lenzen)
        "The Second World War stopped the dig. Julius Jordan died in Berlin on 7 February 1945. Thanks in large part to the Dutch scholar Henri Frankfort, then working in Britain, digging began again in the winter of 1953/54 under Heinrich Lenzen. A year later Lenzen became the first director of the Baghdad branch of the German Archaeological Institute.",

        // Sheet 18 Part A, entry A14 (Lenzen to 1967, Schmidt 1967 to 1977); Open Question 17
        "Lenzen led the work at Uruk until 1967. His team dug craftsmen's quarters, the houses of Neo-Babylonian priests with their own tablet libraries, and the palace of King Sin-kashid. Jürgen Schmidt directed from 1967 to 1977. He dug again at the Anu ziggurat and in late villas, and he added two courtyards to the dig house.",

        // Sheet 18 Part A, entry A14 (Boehmer, the campaigns to 1989); Open Question 18
        "Rainer Michael Boehmer directed the research from 1980 to 1995 and began the series of final reports. War in the region from 1980 allowed only short visits: a survey of the city's surface from 1982 to 1984, and seasons in 1985 and 1989. Counting the seasons in the reports, the 1989 campaign was the thirty-ninth since 1912. Twenty-five volumes of final reports had appeared by 2019.",

        // Sheet 18 Part A, entry A14 (Eichmann and van Ess, the joint project, UNESCO)
        "Since 1996 Margarete van Ess and Ricardo Eichmann of the German Archaeological Institute have led the research, mostly studying the records of the old digs. From 2016 to 2018 German scholars and Iraq's State Board of Antiquities and Heritage worked at Uruk together. In 2016 Uruk became a World Heritage Site, as part of “The Ahwar of Southern Iraq.”",

        // Sheet 18 Part A, entry A14 (2003); sheet 17 and texts/09 (the Heidelberg collection); sheet 20 entry A19 (the site today)
        "In April 2003 thieves broke into the Iraq Museum in Baghdad. They stole the Warka Vase and the Mask of Warka, and both were found again. Where many smaller Uruk finds are today is not certain. More than 7,000 finds from Uruk are kept in the Uruk-Warka collection at Heidelberg University, on long-term loan from the German Archaeological Institute.",

        // Sheet 20 Part A, entry A19 (the site today); Getty 2019 ch. 12 (van Ess)
        "Today the ruins of Uruk lie in the land the Euphrates left behind when it moved west. Because nobody built over the ancient city, much of its architecture survives, Holy Inanna's House of Heaven among it. Illegal digging and modern building now threaten it.",
    };
}
